252	void LCD_ConvertGrayscaleToRGB565(const uint8_t* grayscale, uint16_t* rgb565, size_t size) {
253		for (size_t i = 0; i < size; i++) {
254			uint8_t y = grayscale[i];
255			uint16_t val = ((y >> 3) << 11) | ((y >> 2) << 5) | (y >> 3);
256			rgb565[i] = (val << 8) | (val >> 8); // Swap for display
257		}
258	}
