299	void Paint_NewImage(PAINT* Paint, UWORD Width, UWORD Height, UWORD Rotate, UWORD Color)
300	{
301	    Paint->Image = 0;
302	    Paint->WidthMemory = Width;
303	    Paint->HeightMemory = Height;
304	    Paint->Color = Color;    
305	    Paint->WidthByte = Width;
306	    Paint->HeightByte = Height;    
307	    // printf("WidthByte = %d, HeightByte = %d\r\n", Paint->WidthByte, Paint->HeightByte);
308	   
309	    Paint->Rotate = Rotate;
310	    Paint->Mirror = MIRROR_NONE;
311	    
312	    if(Rotate == ROTATE_0 || Rotate == ROTATE_180) {
313	        Paint->Width = Width;
314	        Paint->Height = Height;
315	    } else {
316	        Paint->Width = Height;
317	        Paint->Height = Width;
