321	void Paint_SetPixel(PAINT* Paint, UWORD Xpoint, UWORD Ypoint, UWORD Color)
322	{
323	    if(Xpoint > Paint->Width || Ypoint > Paint->Height){
324	        // Debug("Exceeding display boundaries\r\n");
325	        return;
326	    }      
327	    UWORD X, Y;
328	
329	    switch(Paint->Rotate) {
330	    case 0:
331	        X = Xpoint;
332	        Y = Ypoint;  
333	        break;
334	    case 90:
335	        X = Paint->WidthMemory - Ypoint - 1;
336	        Y = Xpoint;
337	        break;
338	    case 180:
339	        X = Paint->WidthMemory - Xpoint - 1;
340	        Y = Paint->HeightMemory - Ypoint - 1;
341	        break;
342	    case 270:
343	        X = Ypoint;
344	        Y = Paint->HeightMemory - Xpoint - 1;
345	        break;
346	
347	    default:
348	        return;
349	    }
350	    
351	    switch(Paint->Mirror) {
352	    case MIRROR_NONE:
353	        break;
354	    case MIRROR_HORIZONTAL:
355	        X = Paint->WidthMemory - X - 1;
356	        break;
357	    case MIRROR_VERTICAL:
358	        Y = Paint->HeightMemory - Y - 1;
359	        break;
360	    case MIRROR_ORIGIN:
361	        X = Paint->WidthMemory - X - 1;
362	        Y = Paint->HeightMemory - Y - 1;
363	        break;
364	    default:
365	        return;
366	    }
367	
368	    // printf("x = %d, y = %d\r\n", X, Y);
369	    if(X > Paint->WidthMemory || Y > Paint->HeightMemory){
370	        // Debug("Exceeding display boundaries\r\n");
371	        return;
372	    }
373	    
374	   // UDOUBLE Addr = X / 8 + Y * Paint->WidthByte;
375	   // LCD_DrawPaint(X,Y, Color);
376	   if (Paint->Image) {
377	       Paint->Image[Y * Paint->WidthMemory + X] = Color;
378	   } else {
379	       LCD_DrawPaint(0, X, Y, Color);
380	   }
381	}
