384	void Paint_DrawChar(PAINT* Paint, UWORD Xpoint, UWORD Ypoint, const char Acsii_Char,
385	                    sFONT* Font, UWORD Color_Background, UWORD Color_Foreground)
386	{
387	    UWORD Page, Column;
388	
389	    if (Xpoint > Paint->Width || Ypoint > Paint->Height) {
390	        // Debug("Paint_DrawChar Input exceeds the normal display range\r\n");
391	        return;
392	    }
393	
394	    uint32_t Char_Offset = (Acsii_Char - ' ') * Font->Height * (Font->Width / 8 + (Font->Width % 8 ? 1 : 0));
395	    const unsigned char *ptr = &Font->table[Char_Offset];
396	
397	    for (Page = 0; Page < Font->Height; Page ++ ) {
398	        for (Column = 0; Column < Font->Width; Column ++ ) {
399	
400	            //To determine whether the font background color and screen background color is consistent
401	            if (FONT_BACKGROUND == Color_Background) { //this process is to speed up the scan
402	                if (*ptr & (0x80 >> (Column % 8)))
403	                    Paint_SetPixel(Paint, Xpoint + Column, Ypoint + Page, Color_Foreground);
404	                    // Paint_DrawPoint(Xpoint + Column, Ypoint + Page, Color_Foreground, DOT_PIXEL_DFT, DOT_STYLE_DFT);
405	            } else {
406	                if (*ptr & (0x80 >> (Column % 8))) {
407	                    Paint_SetPixel(Paint, Xpoint + Column, Ypoint + Page, Color_Foreground);
408	                    // Paint_DrawPoint(Xpoint + Column, Ypoint + Page, Color_Foreground, DOT_PIXEL_DFT, DOT_STYLE_DFT);
409	                } else {
410	                    Paint_SetPixel(Paint, Xpoint + Column, Ypoint + Page, Color_Background);
411	                    // Paint_DrawPoint(Xpoint + Column, Ypoint + Page, Color_Background, DOT_PIXEL_DFT, DOT_STYLE_DFT);
412	                }
413	            }
414	            //One pixel is 8 bits
415	            if (Column % 8 == 7)
416	                ptr++;
417	        }// Write a line
418	        if (Font->Width % 8 != 0)
419	            ptr++;
420	    }// Write all
421	}
