423	void Paint_DrawString_EN(PAINT* Paint, UWORD Xstart, UWORD Ystart, const char * pString,
424	                         sFONT* Font, UWORD Color_Background, UWORD Color_Foreground )
425	{
426	    UWORD Xpoint = Xstart;
427	    UWORD Ypoint = Ystart;
428	
429	    if (Xstart > Paint->Width || Ystart > Paint->Height) {
430	        // Debug("Paint_DrawString_EN Input exceeds the normal display range\r\n");
431	        return;
432	    }
433	
434	    while (* pString != '\0') {
435	        //if X direction filled , reposition to(Xstart,Ypoint),Ypoint is Y direction plus the Height of the character
436	        if ((Xpoint + Font->Width ) > Paint->Width ) {
437	            Xpoint = Xstart;
438	            Ypoint += Font->Height;
439	        }
440	
441	        // If the Y direction is full, reposition to(Xstart, Ystart)
442	        if ((Ypoint  + Font->Height ) > Paint->Height ) {
443	            Xpoint = Xstart;
444	            Ypoint = Ystart;
445	        }
446	        Paint_DrawChar(Paint, Xpoint, Ypoint, * pString, Font, Color_Background, Color_Foreground);
447	
448	        //The next character of the address
449	        pString ++;
450	
451	        //The next word of the abscissa increases the font of the broadband
452	        Xpoint += Font->Width;
453	    }
454	}
