17	// Write a single byte to the UART TX register (any 32-bit write sends the
18	// lowest byte as a character on the wire).
19	static inline void uart_write_reg(char c) {
20	    volatile uint32_t *tx = (volatile uint32_t *)UART1_BASE;
21	    *tx = (uint32_t)(uint8_t)c;
22	}
23	
24	void uart_putc(char c) {
25	    uart_write_reg(c);
26	}
27	
28	void uart_puts(const char *s) {
29	    while (*s) {
30	        uart_write_reg(*s);
31	        s++;
32	    }
33	}
