35	void uart_put_hex32(uint32_t val) {
36	    static const char hex[] = "0123456789abcdef";
37	    uart_puts("0x");
38	    for (int i = 28; i >= 0; i -= 4) {
39	        uart_putc(hex[(val >> i) & 0xFU]);
40	    }
