48	void display_renderer_draw_frame(const uint16_t *frame,
49	                                 uint32_t width, uint32_t height) {
50	    void *ctx = display_hal_get_ctx();
51	    LCD_SetWindow(ctx, 0, 0, (UWORD)(width - 1U), (UWORD)(height - 1U));
52	    // Kick off DMA to push the frame buffer directly to the SPI FIFO base.
53	    // In a real driver this would use the DMA to stream to the SPI TX reg;
54	    // here we just DMA to the scratch area as a stub operation.
55	    dma_memcpy(&g_dma, g_scratch, frame,
56	               sizeof(g_scratch) < (width * 2U) ? sizeof(g_scratch)
57	                                                 : width * 2U);
58	    (void)height;
59	}
